"""SQLite-backed repository using append-only IntentStore for events/audit."""

from __future__ import annotations

import os
from typing import Any

from pydantic import ValidationError

from core.intent_store import IntentStore
from core.models import CustomerOutcome, Job, Outcome, Step
from core.repository import Repository


class SQLiteRepository(Repository):
    def __init__(self, db_path: str | None = None) -> None:
        if db_path is None:
            db_path = os.environ.get("AGENTIC_ODI_DB", os.path.expanduser("~/.agentic-odi/odi.db"))
        os.makedirs(os.path.dirname(db_path) or ".", exist_ok=True)
        self.store = IntentStore(db_path)
        # For compatibility with existing semantics, we also maintain a materialized
        # view in memory for fast reads (in-memory snapshot) - simple approach for now.
        self._load_snapshot()

    def _load_snapshot(self) -> None:
        self.jobs: dict[str, Job] = {}
        self.steps: dict[str, Step] = {}
        self.outcomes: dict[str, Outcome] = {}
        self.customer_outcomes: dict[str, CustomerOutcome] = {}
        for ev in self.store.get_stream():
            et = ev["type"]
            p = ev["payload"]
            if et == "JOB_CREATED":
                self.jobs[p["id"]] = Job.model_validate(p)
            elif et == "STEP_CREATED":
                self.steps[p["id"]] = Step.model_validate(p)
            elif et == "OUTCOME_CREATED":
                self.outcomes[p["id"]] = Outcome.model_validate(p)
            elif et == "CUSTOMER_OUTCOME_CREATED":
                self.customer_outcomes[p["id"]] = CustomerOutcome.model_validate(p)

"""CLI adapter for listing, adding, checking, and ingesting external connectors."""

from __future__ import annotations

import asyncio
import os
from pathlib import Path

import typer
from connectors.factory import build_connector
from connectors.models import ConnectorConfig
from connectors.registry import (
    ConnectorNotFoundError,
    ConnectorRegistry,
    DuplicateConnectorError,
    UnknownConnectorKindError,
)
from connectors.sink import get_default_sink

connectors_app = typer.Typer(
    name="connectors",
    help="Connect Agentic ODI to external systems.",
    no_args_is_help=True,
)


def _config_path(config: Path | None) -> Path:
    if config is not None:
        return config
    env = os.getenv("AGENTIC_ODI_CONNECTORS_FILE")
    if env:
        return Path(env)
    return Path.cwd() / ".agentic-odi" / "connectors.json"


def _registry(config: Path | None) -> ConnectorRegistry:
    return ConnectorRegistry(_config_path(config))


ConfigOption = typer.Option(
    None,
    "--config",
    help="Path to the connectors JSON registry.",
    envvar="AGENTIC_ODI_CONNECTORS_FILE",
)


@connectors_app.command("list")
def list_connectors(
    config: Path | None = ConfigOption,
) -> None:
    """List configured external connectors."""
    items = _registry(config).list_all()
    if not items:
        typer.echo("No connectors configured.")
        return
    for item in items:
        status = "enabled" if item.enabled else "disabled"
        typer.echo(f"{item.name}\t{item.kind}\t{status}")


@connectors_app.command("add")
def add_connector(
    kind: str = typer.Argument(..., help="Connector kind (currently: mcp)."),
    name: str = typer.Option(..., "--name", help="Unique connector name."),
    url: str | None = typer.Option(None, "--url", help="MCP server URL (required for kind mcp)."),
    tool: list[str] | None = typer.Option(  # noqa: B008
        None,
        "--tool",
        help="MCP tool to call during ingest. Repeatable.",
    ),
    config: Path | None = ConfigOption,
) -> None:
    """Register a new external connector."""
    settings: dict[str, object] = {}
    if kind == "mcp":
        if not url:
            typer.echo("Error: --url is required for MCP connectors.", err=True)
            raise typer.Exit(code=1)
        settings["url"] = url

